CREATE TEMPORARY VIEW accumulated_list_${grass_region_without_quote} AS
select
     exp_tag
    ,cspu_id
    ,item_id
    ,if(update_flag!='exploring',null,exploration_status) as exploration_status -- 如果不是正在探索中的，则清空探索进度状态，用于下一步的判断
    ,if(update_flag!='exploring',null,filtered_reason) as filtered_reason -- 如果不是正在探索中的，则过滤原因数据重置
    ,if(update_flag!='exploring',new_pruning_tag,current_pruning_tag) as pruning_tag -- 如果不是正在探索中的，则剪枝数据重置
    ,if(update_flag!='exploring',new_version_date,current_version_date) as version_date -- 如果不是正在探索中的，则版本信息重置
from(
    SELECT
         if(a.exp_tag is not null ,a.exp_tag,b.exp_tag) as exp_tag
        ,if(a.cspu_id is not null ,a.cspu_id,b.cspu_id) as cspu_id
        ,if(a.item_id is not null ,a.item_id,b.item_id) as item_id
        ,a.exploration_status
        ,a.filtered_reason
        ,case
           when a.version_date is null and b.version_date is null then 'prepare'
           when a.version_date is null and b.version_date is not null then 'new'
           when a.version_date is not null and b.version_date is not null and a.version_date < b.version_date and a.exploration_status='preferred' then 'rollback'
           else 'exploring'
         end as update_flag
        ,a.version_date as current_version_date
        ,a.pruning_tag as current_pruning_tag
        ,b.version_date as new_version_date
        ,b.pruning_tag as new_pruning_tag
    FROM last_status_${grass_region_without_quote} a
    full outer join pruning_${grass_region_without_quote} b on a.item_id=b.item_id and a.cspu_id=b.cspu_id and a.exp_tag=b.exp_tag
) c
;
