INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_pb_search_replace_status_hf
PARTITION (grass_region = ${grass_region}, regional_date = ${regional_date}, regional_hour = ${regional_hour})
SELECT
     a.exp_tag
    ,a.cspu_id
    ,a.item_id
    ,if(d.item_id is not null,1,0) is_cheapest
    ,a.version_date
    ,a.pruning_tag
    ,if(exploration_status is not null
       ,case -- 如果当前的探索进度不是null，则进行分级探测判断和普通探测判断
          when exploration_status in ('preferred','non_preferred') then exploration_status --探索完成且不升级的，维持原进度不改变
          when pruning_tag='same_with_cspu' then -- 普通探测
            case    -- 这里做了cspu指标的异常值处理，如果cspu指标莫名为null，则按照0计算
                when b.explore_imp_cnt_nd >= 1000 then
                     if(coalesce(b.explore_click_cnt_nd/b.explore_imp_cnt_nd,0) > coalesce(c.cspu_click_cnt_nd/c.cspu_imp_cnt_nd,0)
                     ,'preferred'
                     ,'non_preferred')
                else 'explore' -- 没达到门槛继续探索
            end
          when pruning_tag='long_tail' then -- 长尾走分级探测
            case    -- 这里做了cspu指标的异常值处理，如果cspu指标莫名为null，则按照0计算
                when b.explore_imp_cnt_nd >= 1000 then --分级探测的最后是普通探测
                     if(coalesce(b.explore_click_cnt_nd/b.explore_imp_cnt_nd,0) > coalesce(c.cspu_click_cnt_nd/c.cspu_imp_cnt_nd,0)
                     ,'preferred'
                     ,'non_preferred')
                when b.explore_imp_cnt_nd >= 500 then
                     if(coalesce(b.explore_click_cnt_nd/b.explore_imp_cnt_nd,0) > 0.5*coalesce(c.cspu_click_cnt_nd/c.cspu_imp_cnt_nd,0)
                     ,'explore'
                     ,'non_preferred')
                when b.explore_imp_cnt_nd >= 200 then
                     if(coalesce(b.explore_click_cnt_nd/b.explore_imp_cnt_nd,0) > 0.1*coalesce(c.cspu_click_cnt_nd/c.cspu_imp_cnt_nd,0)
                     ,'explore'
                     ,'non_preferred')
                when b.explore_imp_cnt_nd >= 100 then
                     if(b.explore_click_cnt_nd>=1
                     ,'explore'
                     ,'non_preferred')
                else 'explore'
            end
        end
       ,case
            when pruning_tag ='obvious_good' then 'preferred'
            when pruning_tag in ('obvious_bad','can_not_explore')  then 'non_preferred'
            when pruning_tag is null then 'prepare'
            else 'explore'
        end
     ) as exploration_status
    ,if(exploration_status is not null
       ,case
          when exploration_status in ('preferred','non_preferred') then a.filtered_reason
          when pruning_tag='same_with_cspu' then
            case
                when b.explore_imp_cnt_nd >= 1000 then
                     if(coalesce(b.explore_click_cnt_nd/b.explore_imp_cnt_nd,0) > coalesce(c.cspu_click_cnt_nd/c.cspu_imp_cnt_nd,0)
                     ,null
                     ,'normal_failed')
                else null
            end
          when pruning_tag='long_tail' then -- 分级探测
            case    -- 这里做了cspu指标的异常值处理，如果cspu指标莫名为null，则按照0计算
                when b.explore_imp_cnt_nd >= 1000 then
                     if(coalesce(b.explore_click_cnt_nd/b.explore_imp_cnt_nd,0) > coalesce(c.cspu_click_cnt_nd/c.cspu_imp_cnt_nd,0)
                     ,null
                     ,'tiered_normal_failed')
                when b.explore_imp_cnt_nd >= 500 then
                     if(coalesce(b.explore_click_cnt_nd/b.explore_imp_cnt_nd,0) > 0.5*coalesce(c.cspu_click_cnt_nd/c.cspu_imp_cnt_nd,0)
                     ,null
                     ,'tiered_failed_level_3')
                when b.explore_imp_cnt_nd >= 200 then
                     if(coalesce(b.explore_click_cnt_nd/b.explore_imp_cnt_nd,0) > 0.1*coalesce(c.cspu_click_cnt_nd/c.cspu_imp_cnt_nd,0)
                     ,null
                     ,'tiered_failed_level_2')
                when b.explore_imp_cnt_nd >= 100 then
                     if(b.explore_click_cnt_nd>=1
                     ,null
                     ,'tiered_failed_level_1')
                else null
            end
        end
       ,case
            when pruning_tag ='obvious_good' then null
            when pruning_tag in ('obvious_bad','can_not_explore')  then pruning_tag
            else null
        end
     ) as filtered_reason
FROM accumulated_list_${grass_region_without_quote}  a
left join explore_realtime_metrics_${grass_region_without_quote} b on a.item_id=b.item_id and a.cspu_id=b.cspu_id and a.exp_tag=b.exp_tag and a.version_date=b.version_date
left join control_realtime_metrics_${grass_region_without_quote} c on a.item_id=c.item_id and a.cspu_id=c.cspu_id
left join cheapest_list_${grass_region_without_quote} d on a.item_id=d.item_id and a.cspu_id=d.cspu_id
;
